import sys

def solve(raw: bytes) -> int:
    if not raw:
        return -1
    s_pos = raw.find(b'S')
    e_pos = raw.find(b'E')
    if s_pos == -1 or e_pos == -1:
        return -1
    if s_pos == e_pos:
        return 0

    nl = raw.find(b'\n')
    stride = nl + 1 if nl != -1 else len(raw) + 1
    pad = b'#' * stride
    grid = bytearray(pad + raw + b'\n' + pad)
    s_idx = s_pos + stride
    e_idx = e_pos + stride
    # 46 is '.', mark S side with 1, E side with 2
    grid[s_idx] = 1
    grid[e_idx] = 2

    q_s = [s_idx]
    q_e = [e_idx]
    dist = 0
    while q_s and q_e:
        dist += 1
        if len(q_s) <= len(q_e):
            nxt = []
            append = nxt.append
            for u in q_s:
                for v in (u - stride, u + stride, u - 1, u + 1):
                    g = grid[v]
                    if g == 46:
                        grid[v] = 1
                        append(v)
                    elif g == 2:
                        return dist
            q_s = nxt
        else:
            nxt = []
            append = nxt.append
            for u in q_e:
                for v in (u - stride, u + stride, u - 1, u + 1):
                    g = grid[v]
                    if g == 46:
                        grid[v] = 2
                        append(v)
                    elif g == 1:
                        return dist
            q_e = nxt
    return -1

def main():
    raw = sys.stdin.buffer.read()
    print(solve(raw))

if __name__ == '__main__':
    main()

import ctypes, os, subprocess, sys

_SO_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_maze_c.so")
_C_SRC = r"""
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

int solve_c(const uint8_t *raw, int len) {
    if (len <= 0) return -1;
    int s_pos = -1, e_pos = -1, nl = -1;
    for (int i = 0; i < len; i++) {
        uint8_t c = raw[i];
        if (c == 'S') s_pos = i;
        else if (c == 'E') e_pos = i;
        else if (c == '\n' && nl == -1) nl = i;
    }
    if (s_pos == -1 || e_pos == -1) return -1;
    if (s_pos == e_pos) return 0;
    int stride = (nl != -1) ? (nl + 1) : (len + 1);
    int total = len + 2 * stride + 2;
    uint8_t *vis = (uint8_t *)calloc(total, 1);
    int *q = (int *)malloc((len + 1) * sizeof(int));
    int *dist = (int *)malloc((len + 1) * sizeof(int));
    if (!vis || !q || !dist) {
        free(vis); free(q); free(dist);
        return -1;
    }
    int head = 0, tail = 0;
    q[tail] = s_pos;
    dist[tail] = 0;
    tail++;
    vis[s_pos + stride] = 1;
    int ans = -1;
    int d_offs[4] = {-stride, stride, -1, 1};
    while (head < tail) {
        int u = q[head];
        int d = dist[head];
        head++;
        int nd = d + 1;
        for (int k = 0; k < 4; k++) {
            int v = u + d_offs[k];
            if ((unsigned)v < (unsigned)len && !vis[v + stride]) {
                uint8_t c = raw[v];
                if (c == '.') {
                    vis[v + stride] = 1;
                    q[tail] = v;
                    dist[tail] = nd;
                    tail++;
                } else if (v == e_pos) {
                    ans = nd;
                    goto done;
                }
            }
        }
    }
done:
    free(vis);
    free(q);
    free(dist);
    return ans;
}
"""

if not os.path.exists(_SO_PATH):
    c_path = _SO_PATH + ".c"
    with open(c_path, "w") as f:
        f.write(_C_SRC)
    subprocess.run(["gcc", "-O3", "-shared", "-fPIC", c_path, "-o", _SO_PATH], check=True)

_lib = ctypes.CDLL(_SO_PATH)
