static uint8_t *g_buf = NULL;
static int *g_q = NULL;
static size_t g_cap = 0;

int solve_c(const uint8_t *raw, int len) {
    if (len <= 0) return -1;
    const uint8_t *s_ptr = (const uint8_t *)memchr(raw, 'S', len);
    if (!s_ptr) return -1;
    const uint8_t *e_ptr = (const uint8_t *)memchr(raw, 'E', len);
    if (!e_ptr) return -1;
    int s_pos = (int)(s_ptr - raw);
    int e_pos = (int)(e_ptr - raw);
    if (s_pos == e_pos) return 0;

    const uint8_t *nl_ptr = (const uint8_t *)memchr(raw, '\n', len);
    int stride = nl_ptr ? (int)(nl_ptr - raw) + 1 : (len + 1);
    size_t need = (size_t)len + 2 * (size_t)stride + 4;
    if (need > g_cap) {
        free(g_buf);
        free(g_q);
        g_buf = (uint8_t *)malloc(need);
        g_q = (int *)malloc(need * sizeof(int));
        if (!g_buf || !g_q) { g_cap = 0; return -1; }
        g_cap = need;
    }

    memset(g_buf, '#', stride);
    memcpy(g_buf + stride, raw, len);
    memset(g_buf + stride + len, '#', stride + 4);

    uint8_t *grid = g_buf + stride;
    grid[s_pos] = '#';

    int head = 0, tail = 0;
    g_q[tail++] = s_pos;
    int d = 0;
    int s0 = -stride, s1 = stride;

    while (head < tail) {
        int level_end = tail;
        d++;
        while (head < level_end) {
            int u = g_q[head++];
            int v;
            uint8_t c;

            v = u + s0; c = grid[v];
            if (c == '.') { grid[v] = '#'; g_q[tail++] = v; }
            else if (v == e_pos) return d;

            v = u + s1; c = grid[v];
            if (c == '.') { grid[v] = '#'; g_q[tail++] = v; }
            else if (v == e_pos) return d;

            v = u - 1; c = grid[v];
            if (c == '.') { grid[v] = '#'; g_q[tail++] = v; }
            else if (v == e_pos) return d;

            v = u + 1; c = grid[v];
            if (c == '.') { grid[v] = '#'; g_q[tail++] = v; }
            else if (v == e_pos) return d;
        }
    }
    return -1;
}
"""

